-- GCSE Geography flashcards — paste into the Supabase SQL editor and run once.
--
-- 1. Replaces the Eduqas GCSE deck. Until October 2026 the Eduqas GCSE cards
--    were AQA-style topics (coasts, rivers, glaciation…) stored under the same
--    topic numbers that Eduqas B now uses for different topics, so topic 1.1
--    "Urbanisation in Contrasting Global Cities" showed coastal cards. System
--    cards are not referenced by any user table, so they are deleted and the
--    deck is re-inserted for the real 11 Eduqas B topics.
-- 2. Adds the new AQA (8035), Edexcel B (1GB0) and OCR B (J384) GCSE decks.
--
-- Every INSERT is guarded: it skips fronts already present and never takes a
-- topic past 30 cards, so the whole file is safe to re-run.
BEGIN;

DELETE FROM flashcards
WHERE subject = 'Geography' AND exam_board = 'Eduqas' AND level = 'gcse';

-- Flashcard top-up: Geography|Eduqas|gcse — brings each topic up to 30 cards.
-- Generated by scripts/build-flashcard-topup.js from flashcards/topup/src/geography-eduqas-gcse.txt
-- Safe to re-run: skips fronts already present and never takes a topic past 30.
