  ('Geography', 'AQA', 'gcse', '1.9', 'Glacial Landscapes in the UK', 'What is a pyramidal peak?', 'A sharp mountain peak formed when three or more corries erode back to back.', 7),
  ('Geography', 'AQA', 'gcse', '1.9', 'Glacial Landscapes in the UK', 'What is a U-shaped valley?', 'A wide, flat-bottomed valley with steep sides, formed by a glacier.', 8),
  ('Geography', 'AQA', 'gcse', '1.9', 'Glacial Landscapes in the UK', 'What is a truncated spur?', 'A cut-off end of a spur, eroded by a glacier as it moved down the valley.', 9),
  ('Geography', 'AQA', 'gcse', '1.9', 'Glacial Landscapes in the UK', 'What is a hanging valley?', 'A small valley left high above a main glacial valley, often with a waterfall.', 10),
  ('Geography', 'AQA', 'gcse', '1.9', 'Glacial Landscapes in the UK', 'What is a ribbon lake?', 'A long, narrow lake in the bottom of a U-shaped valley.', 11),
  ('Geography', 'AQA', 'gcse', '1.9', 'Glacial Landscapes in the UK', 'What is moraine?', 'Rocks and sediment deposited by a glacier.', 12),
  ('Geography', 'AQA', 'gcse', '1.9', 'Glacial Landscapes in the UK', 'What is a terminal moraine?', 'A ridge of material marking the furthest point reached by a glacier.', 13),
  ('Geography', 'AQA', 'gcse', '1.9', 'Glacial Landscapes in the UK', 'What is lateral moraine?', 'Material deposited along the sides of a glacier.', 14),
