  ('Geography', 'AQA', 'gcse', '2.3', 'The Changing Economic World', 'What is literacy rate?', 'The percentage of adults who can read and write.', 5),
  ('Geography', 'AQA', 'gcse', '2.3', 'The Changing Economic World', 'What is infant mortality rate?', 'The number of babies who die before their first birthday per 1000 live births.', 6),
