  ('Geography', 'AQA', 'gcse', '2.3', 'The Changing Economic World', 'What is a top-down development project?', 'A large-scale project planned by governments or organisations, e.g. a dam.', 29),
  ('Geography', 'AQA', 'gcse', '2.3', 'The Changing Economic World', 'What is a bottom-up development project?', 'A small-scale project run by local communities, e.g. a village well.', 30),
  ('Geography', 'AQA', 'gcse', '2.4', 'Resource Management', 'Why are food, water and energy significant?', 'They are essential for health, economic development and social wellbeing.', 1),
