  ('Geography', 'OCR', 'gcse', '2.3', 'UK in the 21st Century', 'Why have high streets declined?', 'Online shopping, out-of-town retail parks and high rents.', 27),
  ('Geography', 'OCR', 'gcse', '2.3', 'UK in the 21st Century', 'What is a commuter?', 'Someone who travels from where they live to work in another place.', 28),
  ('Geography', 'OCR', 'gcse', '2.3', 'UK in the 21st Century', 'What is a commuter village?', 'A village where many residents travel to work in a nearby town or city.', 29),
  ('Geography', 'OCR', 'gcse', '2.3', 'UK in the 21st Century', 'What is rural depopulation?', 'The decline in the population of rural areas as people move to cities.', 30),
  ('Geography', 'OCR', 'gcse', '2.4', 'Resource Reliance', 'What share of Tanzanians depend on farming?', 'About two-thirds, mostly small-scale and rain-fed.', 1),
  ('Geography', 'OCR', 'gcse', '2.4', 'Resource Reliance', 'Why is food security a problem in Tanzania?', 'Unreliable rain, poverty, poor roads and storage, and population growth.', 2),
  ('Geography', 'OCR', 'gcse', '2.4', 'Resource Reliance', 'What is a post-harvest loss?', 'Food lost after harvest to pests, damp or poor transport — up to 30–40% of some crops in Tanzania.', 3),
  ('Geography', 'OCR', 'gcse', '2.4', 'Resource Reliance', 'What is SAGCOT?', 'A large-scale scheme developing commercial farming in southern Tanzania.', 4),
  ('Geography', 'OCR', 'gcse', '2.4', 'Resource Reliance', 'Give a criticism of SAGCOT.', 'It could lead to land grabs affecting smallholders.', 5),
  ('Geography', 'OCR', 'gcse', '2.4', 'Resource Reliance', 'Give two small-scale approaches to food security in Tanzania.', 'Hermetic storage bags and conservation agriculture.', 6),
  ('Geography', 'OCR', 'gcse', '2.4', 'Resource Reliance', 'What is food security?', 'When all people always have access to enough safe, nutritious food for a healthy life.', 7),
  ('Geography', 'OCR', 'gcse', '2.4', 'Resource Reliance', 'What is food insecurity?', 'When people lack reliable access to enough affordable, nutritious food.', 8),
  ('Geography', 'OCR', 'gcse', '2.4', 'Resource Reliance', 'Give two areas of food surplus.', 'North America and Europe (also Australia and Argentina).', 9),
  ('Geography', 'OCR', 'gcse', '2.4', 'Resource Reliance', 'Give two areas of food deficit.', 'Much of sub-Saharan Africa and parts of South Asia (also Yemen and Haiti).', 10),
  ('Geography', 'OCR', 'gcse', '2.4', 'Resource Reliance', 'Give two reasons for rising global food consumption.', 'Population growth and economic development increasing meat and dairy demand.', 11),
  ('Geography', 'OCR', 'gcse', '2.4', 'Resource Reliance', 'How do biofuels affect food supply?', 'Land used for fuel crops is not used for food, raising food prices.', 12),
  ('Geography', 'OCR', 'gcse', '2.4', 'Resource Reliance', 'Name two physical factors affecting food supply.', 'Climate (droughts and floods) and pests or disease (e.g. locusts).', 13),
  ('Geography', 'OCR', 'gcse', '2.4', 'Resource Reliance', 'Name two human factors affecting food supply.', 'Conflict and poverty (also technology and water stress).', 14),
  ('Geography', 'OCR', 'gcse', '2.4', 'Resource Reliance', 'What is famine?', 'A widespread, severe shortage of food causing starvation and death.', 15),
  ('Geography', 'OCR', 'gcse', '2.4', 'Resource Reliance', 'What is undernutrition?', 'Not eating enough of the right food, causing stunting and weak immunity.', 16),
  ('Geography', 'OCR', 'gcse', '2.4', 'Resource Reliance', 'How can food insecurity cause soil erosion?', 'Overcultivation and overgrazing remove vegetation, leaving soil bare.', 17),
  ('Geography', 'OCR', 'gcse', '2.4', 'Resource Reliance', 'How can food insecurity cause social unrest?', 'Shortages and high prices lead to protests and riots, e.g. 2008 and the Arab Spring.', 18),
  ('Geography', 'OCR', 'gcse', '2.4', 'Resource Reliance', 'What is irrigation?', 'Artificially watering crops using canals, sprinklers or drip systems.', 19),
  ('Geography', 'OCR', 'gcse', '2.4', 'Resource Reliance', 'Give a disadvantage of irrigation.', 'Salinisation of soils and depletion of rivers and aquifers.', 20),
  ('Geography', 'OCR', 'gcse', '2.4', 'Resource Reliance', 'What is hydroponics?', 'Growing plants with roots in nutrient-rich water instead of soil.', 21),
  ('Geography', 'OCR', 'gcse', '2.4', 'Resource Reliance', 'What is aeroponics?', 'Growing plants with roots in air, misted with nutrient solution.', 22),
  ('Geography', 'OCR', 'gcse', '2.4', 'Resource Reliance', 'What was the Green Revolution?', 'From the 1960s, high-yield seeds, fertilisers and irrigation greatly raised yields in Asia.', 23),
  ('Geography', 'OCR', 'gcse', '2.4', 'Resource Reliance', 'What is the new Green Revolution?', 'Using biotechnology and sustainable methods to raise yields, especially in Africa.', 24),
  ('Geography', 'OCR', 'gcse', '2.4', 'Resource Reliance', 'Give one argument for and one against GM crops.', 'For: higher yields and added nutrients. Against: biodiversity risks and dependence on seed companies.', 25),
  ('Geography', 'OCR', 'gcse', '2.4', 'Resource Reliance', 'What is appropriate technology?', 'Simple, affordable technology suited to local needs and skills, e.g. treadle pumps.', 26),
  ('Geography', 'OCR', 'gcse', '2.4', 'Resource Reliance', 'What is Thanet Earth?', 'The UK''s largest hydroponic greenhouse complex, in Kent, opened in 2008.', 27),
  ('Geography', 'OCR', 'gcse', '2.4', 'Resource Reliance', 'Give an advantage of Thanet Earth.', 'Year-round salad crops, fewer food miles and over 500 jobs.', 28),
  ('Geography', 'OCR', 'gcse', '2.4', 'Resource Reliance', 'Give a disadvantage of Thanet Earth.', 'Built on greenfield farmland; gas-fired power plants emit CO₂; light pollution.', 29),
  ('Geography', 'OCR', 'gcse', '2.4', 'Resource Reliance', 'What is permaculture?', 'Farming that copies natural ecosystems so it maintains its own soil fertility.', 30),
  ('Geography', 'OCR', 'gcse', '3.1', 'Geographical Exploration and Fieldwork', 'How long is OCR B Paper 3?', '1 hour 30 minutes, 60 marks.', 1),
  ('Geography', 'OCR', 'gcse', '3.1', 'Geographical Exploration and Fieldwork', 'What is Paper 3 based on?', 'A resource booklet about a country, given out in the exam.', 2),
  ('Geography', 'OCR', 'gcse', '3.1', 'Geographical Exploration and Fieldwork', 'What does synoptic mean?', 'Linking knowledge from different topics across the course.', 3),
  ('Geography', 'OCR', 'gcse', '3.1', 'Geographical Exploration and Fieldwork', 'Where is fieldwork assessed in OCR B?', 'Physical fieldwork in Paper 1 and human fieldwork in Paper 2.', 4),
  ('Geography', 'OCR', 'gcse', '3.1', 'Geographical Exploration and Fieldwork', 'How many fieldwork enquiries must you complete?', 'Two: one physical and one human, in contrasting environments.', 5),
  ('Geography', 'OCR', 'gcse', '3.1', 'Geographical Exploration and Fieldwork', 'What are the six stages of an enquiry?', 'Question, data collection, processing and presenting, analysing and explaining, conclusions, evaluation.', 6),
  ('Geography', 'OCR', 'gcse', '3.1', 'Geographical Exploration and Fieldwork', 'What is a hypothesis?', 'A statement that can be tested and proved or disproved by an investigation.', 7),
  ('Geography', 'OCR', 'gcse', '3.1', 'Geographical Exploration and Fieldwork', 'What is primary data?', 'Data you collect yourself during fieldwork.', 8),
  ('Geography', 'OCR', 'gcse', '3.1', 'Geographical Exploration and Fieldwork', 'What is secondary data?', 'Data collected by others, e.g. census data, maps or Environment Agency records.', 9),
  ('Geography', 'OCR', 'gcse', '3.1', 'Geographical Exploration and Fieldwork', 'What is random sampling?', 'Every item has an equal chance of being selected.', 10),
  ('Geography', 'OCR', 'gcse', '3.1', 'Geographical Exploration and Fieldwork', 'What is systematic sampling?', 'Taking samples at regular intervals, e.g. every 10 m along a transect.', 11),
  ('Geography', 'OCR', 'gcse', '3.1', 'Geographical Exploration and Fieldwork', 'What is stratified sampling?', 'Sampling sub-groups in proportion to their size in the population.', 12),
  ('Geography', 'OCR', 'gcse', '3.1', 'Geographical Exploration and Fieldwork', 'What does the Bradshaw model predict?', 'Width, depth, velocity and discharge increase downstream; gradient and particle size decrease.', 13),
  ('Geography', 'OCR', 'gcse', '3.1', 'Geographical Exploration and Fieldwork', 'How do you measure river velocity simply?', 'Time a float over a set distance (e.g. 10 m) and repeat three times.', 14),
  ('Geography', 'OCR', 'gcse', '3.1', 'Geographical Exploration and Fieldwork', 'Name two risks in river fieldwork.', 'Slipping or drowning, and waterborne disease such as Weil''s disease.', 15),
  ('Geography', 'OCR', 'gcse', '3.1', 'Geographical Exploration and Fieldwork', 'What is an environmental quality survey?', 'A survey scoring places on features such as litter, graffiti and green space.', 16),
  ('Geography', 'OCR', 'gcse', '3.1', 'Geographical Exploration and Fieldwork', 'Why are environmental quality surveys unreliable?', 'Scoring is subjective and varies between people.', 17),
  ('Geography', 'OCR', 'gcse', '3.1', 'Geographical Exploration and Fieldwork', 'Which graph shows a relationship between two variables?', 'A scatter graph with a line of best fit.', 18),
  ('Geography', 'OCR', 'gcse', '3.1', 'Geographical Exploration and Fieldwork', 'What is a choropleth map?', 'A map shaded in different intensities to show data values for areas.', 19),
  ('Geography', 'OCR', 'gcse', '3.1', 'Geographical Exploration and Fieldwork', 'What is the mean?', 'The total of all values divided by the number of values.', 20),
  ('Geography', 'OCR', 'gcse', '3.1', 'Geographical Exploration and Fieldwork', 'What is the median?', 'The middle value when data is placed in order.', 21),
  ('Geography', 'OCR', 'gcse', '3.1', 'Geographical Exploration and Fieldwork', 'What is the mode?', 'The value that occurs most often.', 22),
  ('Geography', 'OCR', 'gcse', '3.1', 'Geographical Exploration and Fieldwork', 'What is the range?', 'The difference between the highest and lowest values.', 23),
  ('Geography', 'OCR', 'gcse', '3.1', 'Geographical Exploration and Fieldwork', 'What is the interquartile range?', 'The spread of the middle 50% of data — upper quartile minus lower quartile.', 24),
  ('Geography', 'OCR', 'gcse', '3.1', 'Geographical Exploration and Fieldwork', 'What is an anomaly?', 'A result that does not fit the general pattern.', 25),
  ('Geography', 'OCR', 'gcse', '3.1', 'Geographical Exploration and Fieldwork', 'What does correlation not prove?', 'Causation — another factor may cause both variables to change.', 26),
  ('Geography', 'OCR', 'gcse', '3.1', 'Geographical Exploration and Fieldwork', 'What should a fieldwork conclusion do?', 'Answer the original question using evidence from the results.', 27),
  ('Geography', 'OCR', 'gcse', '3.1', 'Geographical Exploration and Fieldwork', 'What does fieldwork evaluation involve?', 'Identifying problems with methods and data, their effects, and improvements.', 28),
  ('Geography', 'OCR', 'gcse', '3.1', 'Geographical Exploration and Fieldwork', 'How can fieldwork reliability be improved?', 'More sites, larger samples, repeat visits and better equipment.', 29),
  ('Geography', 'OCR', 'gcse', '3.1', 'Geographical Exploration and Fieldwork', 'What is a stakeholder?', 'A person or group with an interest in, or affected by, a decision.', 30)
),
fresh AS (
  SELECT v.* FROM v
  WHERE NOT EXISTS (
    SELECT 1 FROM flashcards f
    WHERE f.subject = v.subject AND f.exam_board = v.exam_board AND f.level = v.level
      AND f.topic_id = v.topic_id AND f.front = v.front)
),
cur AS (
  SELECT subject, exam_board, level, topic_id, count(*) AS n, max(card_order) AS mx
  FROM flashcards
  WHERE subject = 'Geography' AND exam_board = 'OCR' AND level = 'gcse'
  GROUP BY 1, 2, 3, 4
),
ranked AS (
  SELECT fr.*, coalesce(c.n, 0) AS n, coalesce(c.mx, 0) AS mx,
         row_number() OVER (PARTITION BY fr.topic_id ORDER BY fr.ord) AS rn
  FROM fresh fr
  LEFT JOIN cur c USING (subject, exam_board, level, topic_id)
)
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level)
SELECT subject, exam_board, topic_id, topic_name, front, back, mx + rn, level
FROM ranked
WHERE n + rn <= 30;

COMMIT;
